class StructureItem {
  final String id;
  final String unit;
  final int dayNumber;
  final String pattern;
  final String definition;
  final String scenario;
  final String uzTranslation;
  final String uzDefinition;
  final List<String> ieltsUse;
  final List<String> examples;
  final List<String> exampleTranslations;

  const StructureItem({
    required this.id,
    required this.unit,
    required this.dayNumber,
    required this.pattern,
    required this.definition,
    required this.scenario,
    required this.uzTranslation,
    required this.uzDefinition,
    required this.ieltsUse,
    required this.examples,
    required this.exampleTranslations,
  });
}

const List<String> kStructureUnits = [
  'Speaking Part 1',
  'Speaking Part 2',
  'Speaking Part 3',
  'Writing Task 2',
];

List<StructureItem> structuresInUnit(String unit) =>
    kStructures.where((s) => s.unit == unit).toList();

/// Groups a unit's structures into ~5-structure "days" (dayNumber), sorted.
Map<int, List<StructureItem>> subUnitsFor(String unit) {
  final inUnit = structuresInUnit(unit);
  final byDay = <int, List<StructureItem>>{};
  for (final s in inUnit) {
    (byDay[s.dayNumber] ??= []).add(s);
  }
  return Map.fromEntries(
    byDay.entries.toList()..sort((a, b) => a.key.compareTo(b.key)),
  );
}

